module benchmark/solution

import std/result (Result, Ok, Err)

type State = Idle | HasCredit(int) | Dispensing(int)
type Event = Insert(int) | Select(int) | DispenseDone

pure func selectItem(credit: int, code: int) -> Result[State, string] {
  let price = match code { 1 => 125, 2 => 75, 3 => 100, _ => 0 };
  if price == 0 then Err("unknown_item")
  else if credit < price then Err("insufficient_funds")
  else Ok(Dispensing(credit - price))
}

pure func step(state: State, event: Event) -> Result[State, string] =
  match (state, event) {
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),
    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) => selectItem(c, code),
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),
    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(_), DispenseDone) => Ok(Idle)
  }

func simulate(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    event :: rest => match step(state, event) {
      Ok(next) => {
        println(match next {
          Idle => "ok: IDLE",
          HasCredit(n) => "ok: CREDIT(${show(n)})",
          Dispensing(change) => "ok: DISPENSING(${show(change)})"
        });
        simulate(next, rest)
      },
      Err(reason) => {
        println("err: ${reason}");
        simulate(state, rest)
      }
    }
  }

export func main() -> () ! {IO} =
  simulate(Idle, [Insert(50), Select(1), Insert(100), Select(1),
    Insert(50), DispenseDone, Select(2), Insert(100), Select(2), DispenseDone])
